const p = {{ json .proposal }};
const sf = {{ json .source_file }}; const rf = {{ json .review_file }};
const s = JSON.parse(sf.content); const r = JSON.parse(rf.content);
const checked_at = new Date().toISOString();
const base = {citations:[], warning:"exact_revision_not_current_page", checked_at, expires_at:p.review_due, proposal_id:p.proposal_id};
if (r.proposal_id!==p.proposal_id || r.source_id!==p.source_id || r.evidence_quote!==p.evidence_quote || !["validated","refused","disputed"].includes(r.decision)) return {...base,answer:"",status:"review_invalid"};
if (r.decision!=="validated") return {...base,answer:"",status:r.decision};
if (typeof p.review_due!=="string" || Number.isNaN(Date.parse(p.review_due))) return {...base,answer:"",status:"review_date_invalid"};
if (Date.parse(p.review_due)<=Date.now()) return {...base,answer:"",status:"expired"};
if (s.source_id!==p.source_id || typeof s.content!=="string" || typeof p.evidence_quote!=="string" || !p.evidence_quote.trim() || !s.content.includes(p.evidence_quote) || typeof s.ref!=="string" || !s.ref.trim()) return {...base,answer:"",status:"evidence_changed"};
return {...base,answer:p.content,citations:[s.ref],status:"validated"};
